using System.Globalization;

int count = 0, sum = 0, min = int.MaxValue, max = int.MinValue;
while (true)
{
    Console.Write("Number? ");
    string? line = Console.ReadLine();
    if (line == null || line.Trim() == "done") break;
    if (!int.TryParse(line.Trim(), out int n))
    {
        Console.WriteLine($"Not a number: {line}");
        continue;
    }
    count++;
    sum += n;
    min = Math.Min(min, n);
    max = Math.Max(max, n);
}

if (count == 0)
{
    Console.WriteLine("No numbers.");
}
else
{
    Console.WriteLine($"Count: {count}");
    Console.WriteLine($"Sum: {sum}");
    Console.WriteLine($"Min: {min}");
    Console.WriteLine($"Max: {max}");
    Console.WriteLine($"Average: {((double)sum / count).ToString("F2", CultureInfo.InvariantCulture)}");
}
